import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as d,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"通义灵码 Cheatsheet","description":"通义灵码 / Qoder CN 安装入口、兼容版本、快捷键、会话模式、套餐与官方数据源。只抄能打开的官方页。","frontmatter":{"title":"通义灵码 Cheatsheet","description":"通义灵码 / Qoder CN 安装入口、兼容版本、快捷键、会话模式、套餐与官方数据源。只抄能打开的官方页。","domain":"product","tags":["coding-agent"],"role":"cheatsheet"},"headers":[],"relativePath":"zh/products/lingma/lingma-cheatsheet.md","filePath":"zh/products/lingma/lingma-cheatsheet.md","lastUpdated":1787107158000}'),o={name:"zh/products/lingma/lingma-cheatsheet.md"};function n(l,t,i,h,s,c){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="通义灵码-cheatsheet" tabindex="-1">通义灵码 Cheatsheet <a class="header-anchor" href="#通义灵码-cheatsheet" aria-label="Permalink to &quot;通义灵码 Cheatsheet&quot;">​</a></h1><blockquote><p><strong>参考页</strong>。只查不学。概念看 <a href="./lingma-glossary.html">术语表</a>，上手看 <a href="./lingma.html">教程</a>。</p><p>最后核实：2026-08-19。套餐和快捷键以打开的官方页为准；帮助中心与 <a href="https://docs.qoder.cn/" target="_blank" rel="noreferrer">docs.qoder.cn</a> 打架时，在表里同时记下，不抹平。</p></blockquote><h2 id="术语索引" tabindex="-1">术语索引 <a class="header-anchor" href="#术语索引" aria-label="Permalink to &quot;术语索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话</th></tr></thead><tbody><tr><td><a href="./lingma-glossary.html#通义灵码--qoder-cn">通义灵码 / Qoder CN</a></td><td>阿里云编码助手；2026-05-20 更名</td></tr><tr><td><a href="./lingma-glossary.html#qoder-cn-ide--lingma-ide">Qoder CN IDE</a></td><td>独立 IDE，营销站仍写 Lingma IDE</td></tr><tr><td><a href="./lingma-glossary.html#ide-插件">IDE 插件</a></td><td>JetBrains / VS Code / Visual Studio</td></tr><tr><td><a href="./lingma-glossary.html#智能问答--文件编辑--智能体">智能问答 / 文件编辑 / 智能体</a></td><td>三种会话模式，不是三个产品</td></tr><tr><td><a href="./lingma-glossary.html#nes-行间建议预测">NES</a></td><td>下一处修改预测</td></tr><tr><td><a href="./lingma-glossary.html#credits">Credits</a></td><td>2026-05-20 起的用量单位</td></tr><tr><td><a href="./lingma-glossary.html#不是什么">通义千问 / 百炼</a></td><td>同厂其它产品，本目录不写</td></tr></tbody></table><h2 id="安装入口" tabindex="-1">安装入口 <a class="header-anchor" href="#安装入口" aria-label="Permalink to &quot;安装入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>官方入口</th><th>原文要点</th></tr></thead><tbody><tr><td>Qoder CN IDE</td><td><a href="https://qoder.com.cn/download" target="_blank" rel="noreferrer">qoder.com.cn/download</a></td><td>帮助中心指定的 IDE 下载地址</td></tr><tr><td>Lingma IDE（旧品牌页）</td><td><a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">lingma.aliyun.com/download</a></td><td>营销站仍用此名</td></tr><tr><td>JetBrains 市场</td><td>IDE 插件页搜 <strong>通义灵码（TONGYI Lingma）</strong> 或 <strong>Qoder CN</strong></td><td>两套展示名都是官方原文</td></tr><tr><td>JetBrains 离线包</td><td><a href="https://tongyi-code.oss-cn-hangzhou.aliyuncs.com/jetbrain/tongyi-jetbrains-latest.zip" target="_blank" rel="noreferrer">tongyi-jetbrains-latest.zip</a></td><td>帮助中心</td></tr><tr><td>JetBrains 离线包（新品牌）</td><td><a href="https://qodercn-jb.oss-cn-hangzhou.aliyuncs.com/qodercn-jetbrains-latest.zip" target="_blank" rel="noreferrer">qodercn-jetbrains-latest.zip</a></td><td>qoder.com.cn</td></tr><tr><td>VS Code 市场</td><td><code>vscode:extension/Alibaba-Cloud.tongyi-lingma</code></td><td>帮助中心「立即安装」</td></tr><tr><td>VS Code VSIX</td><td><a href="https://tongyi-code.oss-cn-hangzhou.aliyuncs.com/vscode/tongyi-lingma-latest.vsix" target="_blank" rel="noreferrer">tongyi-lingma-latest.vsix</a></td><td>帮助中心</td></tr><tr><td>安装总入口</td><td><a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">安装指南</a></td><td>IDE + JetBrains + VS Code 逐步说明</td></tr><tr><td>登录总入口</td><td><a href="https://help.aliyun.com/zh/lingma/installation-and-login-guide/" target="_blank" rel="noreferrer">安装和登录</a></td><td>个人 / 企业标准 / 企业专属</td></tr></tbody></table><p>逐步原文见 <a href="./lingma.html#第-1-步装上">教程 · 第 1 步</a>。</p><h2 id="兼容-ide-和系统" tabindex="-1">兼容 IDE 和系统 <a class="header-anchor" href="#兼容-ide-和系统" aria-label="Permalink to &quot;兼容 IDE 和系统&quot;">​</a></h2><p>来源：<a href="https://help.aliyun.com/zh/lingma/compatible-ide-and-system" target="_blank" rel="noreferrer">兼容 IDE 和系统</a>、<a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">什么是 Qoder CN</a>。</p><table tabindex="0"><thead><tr><th>客户端</th><th>IDE / 系统门槛</th></tr></thead><tbody><tr><td>Qoder CN IDE</td><td>Windows 10/11（x64；产品页另写 arm64）、macOS 11.0+；安装指南另列 Linux x64 <code>.deb</code>/<code>.rpm</code></td></tr><tr><td>JetBrains IDEs</td><td>2020.3+：IntelliJ IDEA、PyCharm、GoLand、WebStorm、Android Studio、HUAWEI DevEco Studio 等；Windows 7+ / macOS / Linux</td></tr><tr><td>Visual Studio Code</td><td>1.68.0+；Windows 7+ / macOS / Linux</td></tr><tr><td>Visual Studio</td><td>2022 17.3.0+ 或 2019 16.3.0+；Windows 10+</td></tr><tr><td>其它场景</td><td>Remote SSH、WSL；VS Code WebIDE / Open VSX</td></tr></tbody></table><p>官方补充：迭代集中在 <strong>Qoder CN IDE + JetBrains 插件</strong>；VS Code 更新放缓。新文档站写 VS Code 插件已停止维护。</p><p>支持语言（产品页 / 帮助中心）：Java、Python、Go、C#、C/C++、JavaScript、TypeScript、PHP、Ruby、Rust、Scala、Kotlin 等。营销站另写「200 种语言」——本表只收录帮助中心点名的主流语言。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><p>来源：<a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">智能会话概览</a>、<a href="https://help.aliyun.com/zh/lingma/next-edit-suggestion" target="_blank" rel="noreferrer">行间建议预测</a>、<a href="https://help.aliyun.com/zh/lingma/plug-in-configuration-guide" target="_blank" rel="noreferrer">插件配置</a>。未在官方表里出现的键不收录。</p><table tabindex="0"><thead><tr><th>操作</th><th>macOS</th><th>Windows</th></tr></thead><tbody><tr><td>打开 / 关闭智能会话（JetBrains、VS Code）</td><td><code>⌘ ⇧ L</code></td><td><code>Ctrl Shift L</code></td></tr><tr><td>打开 / 关闭智能会话（Lingma IDE）</td><td><code>⌘ L</code></td><td><code>Ctrl Shift L</code></td></tr><tr><td>接受行间代码建议</td><td><code>Tab</code></td><td><code>Tab</code></td></tr><tr><td>接受 NES</td><td><code>Tab</code></td><td><code>Tab</code></td></tr><tr><td>拒绝 NES</td><td><code>Esc</code></td><td><code>Esc</code></td></tr><tr><td>打开个人设置（开启 NES）</td><td><code>⌘ ⇧ ,</code></td><td><code>Ctrl Shift ,</code></td></tr></tbody></table><p>VS Code 新建会话还可在输入框输入 <code>/</code> 后选 <code>/newChat</code>（官方：仅 VS Code）。智能体规划可用 <code>/plan</code>。</p><h2 id="会话模式" tabindex="-1">会话模式 <a class="header-anchor" href="#会话模式" aria-label="Permalink to &quot;会话模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>智能问答</th><th>文件编辑</th><th>智能体</th></tr></thead><tbody><tr><td>改文件</td><td>否</td><td>是（你给的范围）</td><td>是（自己拆任务）</td></tr><tr><td>跑终端</td><td>否</td><td>否</td><td>是（默认先确认）</td></tr><tr><td>VS Code</td><td>支持</td><td>支持</td><td>支持</td></tr><tr><td>Lingma IDE / JetBrains</td><td>支持</td><td><strong>不支持</strong></td><td>支持</td></tr><tr><td>Visual Studio</td><td>支持</td><td>未写支持</td><td>未写支持</td></tr></tbody></table><h2 id="套餐-只抄打开的官方表" tabindex="-1">套餐（只抄打开的官方表） <a class="header-anchor" href="#套餐-只抄打开的官方表" aria-label="Permalink to &quot;套餐（只抄打开的官方表）&quot;">​</a></h2><p>来源：<a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">计费说明</a>，2026-08-19 打开的「Qoder CN（全家桶）」页签。<strong>价格会变，下单前打开官方页。</strong></p><p>官方前提：</p><ul><li>2026-05-20 23:00:00（北京时间）起启用新定价和 Credits。</li><li>个人专业版限免已于 2026-05-20 18:00:00 结束。</li><li>2026-06-20 起，全家桶个人版 Credits 可在 Desktop、JetBrains 插件、QoderWork、CLI、Wake、Mobile 间共享。</li><li>该页写「VSC 插件停止演进」。</li></ul><table tabindex="0"><thead><tr><th>版本</th><th>单价（官方表）</th><th>Credits（官方表）</th></tr></thead><tbody><tr><td>个人体验版（Free）</td><td>免费</td><td>有限体验额度；2 周试用及 300 Credits</td></tr><tr><td>个人专业版（Pro）</td><td>59 元 / 月</td><td>2,000 Credits / 月</td></tr><tr><td>个人高级版（Pro+）</td><td>169 元 / 月</td><td>6,000 Credits / 月</td></tr><tr><td>团队版（Teams）</td><td>99 元 / 席位·月</td><td>3,000 Credits / 席位·月</td></tr><tr><td>企业标准版（Enterprise）</td><td>149 元 / 席位·月</td><td>3,000 Credits / 席位·月，可共享；10 席位起</td></tr><tr><td>企业专属版（Enterprise VPC）</td><td>199 元 / 席位·月</td><td>3,000 Credits / 席位·月，可共享；50 席位起</td></tr></tbody></table><p>「Qoder CN（原灵码）」页签是 IDE / JetBrains / VS Code <strong>单产品企业订阅</strong>：企业标准版 99 元 / 席位·月，企业专属版 199 元 / 席位·月。存量 2026-05-20 前合同见该页第三个页签，本表不抄旧价以免和下单页打架。</p><p>资源包（原灵码个人）：40 元 / 1,000 Credits，有效期 1 个月。企业：80 元 / 2,000 Credits，有效期 3 个月。到期未用完清零。</p><h2 id="高质量信息源" tabindex="-1">高质量信息源 <a class="header-anchor" href="#高质量信息源" aria-label="Permalink to &quot;高质量信息源&quot;">​</a></h2><p>最后核实：2026-08-19。按可信度排序。社区评测只作线索，不进套餐和命令。</p><h3 id="一手官方" tabindex="-1">一手官方 <a class="header-anchor" href="#一手官方" aria-label="Permalink to &quot;一手官方&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://lingma.aliyun.com/" target="_blank" rel="noreferrer">lingma.aliyun.com</a></td><td>旧品牌营销首页，本 issue 指定起点</td></tr><tr><td><a href="https://lingma.aliyun.com/download" target="_blank" rel="noreferrer">lingma.aliyun.com/download</a></td><td>Lingma IDE + JetBrains 安装原文</td></tr><tr><td><a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">qoder.com.cn</a></td><td>新品牌站</td></tr><tr><td><a href="https://qoder.com.cn/download" target="_blank" rel="noreferrer">qoder.com.cn/download</a></td><td>帮助中心指定的 IDE 下载页</td></tr><tr><td><a href="https://docs.qoder.cn/" target="_blank" rel="noreferrer">docs.qoder.cn</a></td><td>官方标为最新的文档站</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/introduction-of-lingma" target="_blank" rel="noreferrer">什么是 Qoder CN 系列</a></td><td>家族图</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">什么是 Qoder CN</a></td><td>编码子产品能力</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/installation-guide" target="_blank" rel="noreferrer">安装指南</a></td><td>IDE / JetBrains / VS Code 安装</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/installation-and-login-guide/" target="_blank" rel="noreferrer">安装和登录</a></td><td>登录分流</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/individual-edition-quick-start" target="_blank" rel="noreferrer">个人版快速入门</a></td><td>个人账号路径</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/compatible-ide-and-system" target="_blank" rel="noreferrer">兼容 IDE 和系统</a></td><td>版本门槛</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">智能会话概览</a></td><td>三模式 + 快捷键</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/agent" target="_blank" rel="noreferrer">智能体</a></td><td><code>/plan</code>、终端确认、Auto-Run</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/guide-for-using-mcp" target="_blank" rel="noreferrer">MCP</a></td><td>MCP 配置</td></tr><tr><td><a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">计费说明</a></td><td>价格与 Credits</td></tr><tr><td><a href="https://marketplace.visualstudio.com/items?itemName=Alibaba-Cloud.tongyi-lingma" target="_blank" rel="noreferrer">VS Marketplace · Alibaba-Cloud.tongyi-lingma</a></td><td>插件 ID 与英文产品说明</td></tr><tr><td><a href="https://www.alibabacloud.com/help/en/lingma/" target="_blank" rel="noreferrer">国际站帮助</a></td><td>英文对照</td></tr></tbody></table><h3 id="同厂但不在本目录展开" tabindex="-1">同厂但不在本目录展开 <a class="header-anchor" href="#同厂但不在本目录展开" aria-label="Permalink to &quot;同厂但不在本目录展开&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a></td><td>通义千问</td></tr><tr><td><a href="https://www.aliyun.com/product/bailian" target="_blank" rel="noreferrer">阿里云百炼</a></td><td>模型平台</td></tr><tr><td><a href="https://qoder.com.cn/cli" target="_blank" rel="noreferrer">Qoder CN CLI</a></td><td>终端子产品</td></tr></tbody></table>',31)])])}const u=e(o,[["render",n]]);export{f as __pageData,u as default};
